/**
 * The text of the generated files. Nothing here reads the clock, the machine
 * or the commit: a commit in the text would change every target's key.
 *
 * @since 0.1.0
 */

import * as Result from "effect/Result"
import { commitQuestion, type Inventory, stepTimeoutHours, type Toolchain } from "../contract/Inventory.ts"
import type { Failure, GeneratedFile, GenerateOptions } from "../contract/Parts.ts"
import { path as targetMapPath, type TargetMap } from "../contract/TargetMap.ts"
import { variantKey } from "./Expressions.ts"
import { type Leg, repositoryLabel, type StepPlan, type StepTarget, workflowPath } from "./Steps.ts"
import * as Yaml from "./Yaml.ts"

// The name of the generated workspace's cache directory. The directory itself is outside the checkout.
const cacheDirectory = ".flows"

export { workflowPath }

/**
 * The generated workspace declaration, which also holds every generated
 * target. It is Smithers build's plain workspace file: JavaScript under a name
 * no type checker, linter or formatter reads as one of the repository's own
 * files, in a directory whose name starts with a dot. A repository's `tsc`,
 * ESLint or Prettier run over its root never sees it.
 *
 * The targets are the root package because a glob sees only its own package,
 * and a step can read any file. A directory with its own `PACKAGE.ts` is
 * another package, which the root glob skips.
 *
 * @category constants
 * @since 0.1.0
 */
export const workspacePath = ".smithers/WORKSPACE.smithers"

/**
 * The file holding every generated target: the workspace declaration.
 *
 * @category constants
 * @since 0.1.0
 */
export const packagePath = workspacePath

/**
 * What the original CI does that the targets do not. Kept out of the file
 * that holds the targets, which has a size limit. It is plain text: a
 * repository's Markdown formatter and linter leave a `.txt` file alone.
 *
 * @category constants
 * @since 0.1.0
 */
export const notesPath = ".smithers/ci/NOT-REPRODUCED.txt"

/**
 * Keeps everything under `.smithers/` out of the package `npm pack` and
 * `npm publish` build. npm reads an `.npmignore` in any directory, so the
 * repository's own ignore files stay as they are.
 *
 * @category constants
 * @since 0.1.0
 */
export const packIgnorePath = ".smithers/.npmignore"

/**
 * Which machine of the generated workflow runs which target, when targets
 * need different tool versions: one `<leg> <label>` per line. A label list
 * this long does not fit in the workflow's own text.
 *
 * @category constants
 * @since 0.1.0
 */
export const legsPath = ".smithers/ci/legs.txt"

const generated = "Generated by smithers-ci. Do not edit."

// The release of smithers-ci and of @smthrs/cli, released together, that the workflow installs.
const release = "1.0.0-rc.18"

// Above this many targets they share one file group. Each target otherwise
// lists every file in the plan, which outgrows a string on a large repository.
const sharedInputsAbove = 32

// Smithers refuses a larger declaration file.
const maximumPackageBytes = 1024 * 1024

/**
 * Where Node keeps the compiled code of `smthrs` between runs, in the
 * directory Smithers build keeps its cache in. The workflow sets it and
 * carries it from one run to the next; a replay starts `smthrs` with the same
 * directory.
 *
 * @category constants
 * @since 0.1.0
 */
export const compiledCode = "node-compile-cache"

/**
 * Where the generated workflow keeps what Smithers build keeps between runs,
 * on a runner: a directory of the runner, outside the checkout, which the
 * workflow saves and restores. A step that lists its checkout finds nothing
 * of Smithers CI there.
 *
 * @category constants
 * @since 0.1.0
 */
export const stateDirectory = "${{ runner.temp }}/smithers-ci"

/**
 * Where Smithers build keeps what each observed step left, in its cache
 * directory: the generated workflow carries it from one run to the next with
 * the results, so a step that has to run finds what the steps before it left
 * without running them.
 *
 * @category constants
 * @since 0.1.0
 */
export const keptFiles = "kept"

// The limit a baseline step has, which is GitHub's for a job; the build's own default is 30 minutes.
const stepTimeout = `${stepTimeoutHours}h`

const setupActions: ReadonlyMap<string, { readonly uses: string; readonly input: string }> = new Map([
  ["bun", { uses: "oven-sh/setup-bun@v2", input: "bun-version" }],
  ["go", { uses: "actions/setup-go@v5", input: "go-version" }],
  ["just", { uses: "extractions/setup-just@v3", input: "just-version" }],
  ["node", { uses: "actions/setup-node@v4", input: "node-version" }],
  ["pnpm", { uses: "pnpm/action-setup@v4", input: "version" }],
  ["python", { uses: "actions/setup-python@v5", input: "python-version" }],
  ["rust", { uses: "dtolnay/rust-toolchain@stable", input: "toolchain" }],
  ["zig", { uses: "mlugg/setup-zig@v2", input: "version" }]
])

const text = (value: string): string => JSON.stringify(value)

const comment = (value: string): string => `// ${value.replace(/[\r\n\u2028\u2029]+/g, " ")}`

// A comment line of a plain text file, such as an ignore file.
const hashComment = (value: string): string => `# ${value}`

const workspaceName = (repository: string): string => {
  const name = repository.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[^A-Za-z0-9]+/, "")
  return name === "" ? "repository" : name
}

const renderWorkspace = (inventory: Inventory): ReadonlyArray<string> => [
  `export const Workspace = S.Workspace(${text(workspaceName(inventory.repository))}, {`,
  `  repository: ${text(inventory.repository)},`,
  // Outside the checkout: a step that lists its files finds the repository's and nothing of Smithers build's.
  // `goBuild: false`: a step's `go` keeps its cache in the step's own home, as on the runner, and never in this
  // directory, which outlives the job. Go would answer a later run from a test result kept there.
  `  cache: S.Cache({ directory: ${JSON.stringify(cacheDirectory)}, outside: true, goBuild: false }),`,
  `  host: S.Host({ bins: ["bash", "sh"] })`,
  `})`,
  ``
]

// True for a target held to its step's inputs by the read sandbox.
const narrows = (target: StepTarget, narrowed: boolean): boolean =>
  narrowed && target.rule === "check" && target.inputs !== undefined && !target.keeps

// Paths a tool writes as it runs and never reads to decide its result: npm keeps a log of every command in the
// first, Node keeps the code it compiled in the second, which it checks against the source before it uses it and
// which is not the same bytes from one run to the next, and Go's tools count their runs in the third. Left out of
// what an observed step read, they cannot make it run again. A job's temporary directory is empty when the job
// starts, so a step that read the compiled code an earlier step of its job left would never be reused.
const bookkeeping: ReadonlyArray<string> = ["~/.npm/_logs", "$TMPDIR/node-compile-cache", "~/.config/go/telemetry"]

// True for a setup target that names what it reads and what it writes. It is a build that always runs: its inputs
// enter the key of every target after it, and its outputs enter their read set.
const builds = (target: StepTarget, narrowed: boolean): boolean =>
  narrowed && target.rule === "setup" && target.outputs !== undefined

// True for a target whose step does not say what it reads. Smithers build observes it: the run is traced, the
// result is stored with every path the run looked at, and the target runs again only when one of those paths
// changed. A setup target is observed too: what it left for the steps after it is kept with its record and put back
// when one of them has to run.
//
// A step that keeps files in the build's cache directory from one run to the next is not observed: no record
// holds what it found there, so it always runs, as a step that restores a cache must.
const observes = (target: StepTarget, narrowed: boolean): boolean =>
  !narrows(target, narrowed) && !builds(target, narrowed) && !target.keeps

// The files a target declares.
//
// A setup target that names what it reads and what it writes declares both.
// Any other setup target declares no files: a setup target that declared the
// repository would change the key of every target after it on any change, and
// a target after it declares the whole repository itself.
//
// Any other target declares its step's inputs, or the whole repository when
// `inputs` is `undefined`.
const filesOf = (target: StepTarget, narrowed: boolean): ReadonlyArray<string> => {
  if (narrowed && target.inputs !== undefined) return target.inputs.map((input) => `S.glob(${text(`//${input}`)})`)
  return target.rule === "setup" ? [] : ["repository"]
}

// What a setup target that is a build declares it writes: the step's own outputs. It runs every time and its
// result is never reused.
const outputsOf = (target: StepTarget): ReadonlyArray<string> => {
  const own = target.outputs as NonNullable<StepTarget["outputs"]>
  return [
    ...(own.files.length === 0 ? [] : [`outFiles: [${own.files.map((file) => text(`//${file}`)).join(", ")}]`]),
    ...(own.directories.length === 0
      ? []
      : [`outDirs: [${own.directories.map((directory) => text(`//${directory}`)).join(", ")}]`]),
    `cache: false`
  ]
}

// The variables of the machine a target passes to its step with their values in its key: the ones its step names,
// and `passed`, the ones every target passes. A variable the step sets itself keeps the step's value. The
// variables a run gives are among them only for a target that is neither observed nor held to its inputs: nothing
// then says whether its step could use one, so each value is part of its key.
const inheritedBy = (target: StepTarget, passed: ReadonlyArray<string>, told: boolean): ReadonlyArray<string> =>
  [
    ...new Set([
      ...target.inheritEnv,
      ...(told ? [] : target.runEnv),
      ...passed.filter((name) => !Object.hasOwn(target.env, name))
    ])
  ].sort((left, right) => left < right ? -1 : 1)

// What tells as much of a run as the variables it gives: where the event file is. A step that reads the file reads
// the commit.
const runNames: ReadonlyArray<string> = ["GITHUB_EVENT_PATH"]

// What a target held to its inputs asks Smithers build for the variables a run gives. The step can read no file
// of the repository but its inputs, so the values are part of its key only when its text or one of those files
// names one. Any other held step is reused at another commit, from a shared cache too.
const given = (target: StepTarget): string =>
  `given: { env: ${JSON.stringify(target.runEnv)}, names: ${JSON.stringify(runNames)} }`

// What an observed target asks Smithers build to record. The variables a run gives are passed on with their values
// out of the key: a result holds the value of each one its run could have used, and is reused at another commit
// when it used none. Where no run gives them, as when a person runs the targets, the runner text asks git, and
// what that git reads is none of the step's (`Inventory.commitQuestion`). What the target writes at the same time
// as the targets beside it (`Step.shares`) is left out with the bookkeeping: one of them changes it while another
// runs, and a run stores nothing over a file somebody else changed.
const observation = (target: StepTarget): string =>
  `observe: { ignore: ${JSON.stringify([...bookkeeping, ...target.shares])}${
    target.runEnv.length === 0
      ? ""
      : `, env: ${JSON.stringify(target.runEnv)}, quiet: ${JSON.stringify([commitQuestion])}`
  } }`

const renderTarget = (
  target: StepTarget,
  index: number,
  variables: ReadonlyMap<string, string>,
  narrowed: boolean,
  passed: ReadonlyArray<string>
): string => {
  const data = [...filesOf(target, narrowed), ...target.dependencies.map((label) => variables.get(label) as string)]
  const observed = observes(target, narrowed)
  const held = narrows(target, narrowed) && target.runEnv.length > 0
  const inheritEnv = inheritedBy(target, passed, observed || held)
  const build = builds(target, narrowed)
  const fields = [
    `shell: ${text(target.script)}`,
    ...(build ? outputsOf(target) : target.keeps ? [`cache: false`] : []),
    ...(Object.keys(target.env).length === 0 ? [] : [`env: ${JSON.stringify(target.env)}`]),
    ...(inheritEnv.length === 0 ? [] : [`inheritEnv: ${JSON.stringify(inheritEnv)}`]),
    ...(target.host === undefined ? [] : [`hosts: [${text(target.host)}]`]),
    // A target that declares what it reads is held to it: a read outside its
    // inputs fails the target instead of passing on a stale result. The
    // network stays open, as it is for the step in the original CI.
    `sandbox: ${narrows(target, narrowed) ? "{ network: true }" : text("none")}`,
    ...(observed ? [observation(target)] : []),
    ...(held ? [given(target)] : []),
    // The steps of one job share a checkout, a home and a temporary directory no other job sees.
    ...(target.machine === undefined ? [] : [`machine: ${text(target.machine)}`]),
    `timeout: ${text(stepTimeout)}`,
    `data: [${data.join(", ")}]`
  ]
  return [
    comment(target.title),
    ...target.also.map((same) => comment(`${same.title}: the same step, run once`)),
    `const step${index} = S.Shell.${build || target.keeps ? "Build" : "Test"}({`,
    fields.map((field) => `  ${field}`).join(",\n"),
    `})`,
    ``
  ].join("\n")
}

// The workspace and every target, in the one file Smithers build reads.
const renderDeclaration = (
  inventory: Inventory,
  plan: StepPlan,
  narrowed: boolean,
  passed: ReadonlyArray<string>
): string => {
  const shared = plan.targets.length > sharedInputsAbove
  const variables = new Map(plan.targets.map((target, index) => [target.label, `step${index}`]))
  return [
    comment(generated),
    ...(plan.notes.length === 0 ? [] : [comment(`Not reproduced from the original CI: see ${notesPath}`)]),
    comment(
      "Smithers build reads this file. Its name keeps it out of the repository's own type check, lint and format."
    ),
    `import { Smithers as S } from "@smthrs/targets"`,
    ``,
    ...renderWorkspace(inventory),
    comment("A step can read any file, so a target declares the whole repository unless its step names what it reads."),
    comment("Such a target is observed: it runs again only when a file its last run read has changed."),
    comment("What a step left for the steps after it is kept, and put back when one of them has to run."),
    comment(
      "The targets of one job name the job's machine, with a checkout, a home and a temporary directory of its own."
    ),
    `const repository = ${shared ? `S.Filegroup({ srcs: [S.glob("//**")] })` : `S.glob("//**")`}`,
    ``,
    ...plan.targets.map((target, index) => renderTarget(target, index, variables, narrowed, passed)),
    `export const Package = S.Package({`,
    `  targets: {`,
    [
      ...(shared ? [`    ${text(repositoryLabel)}: repository`] : []),
      ...plan.targets.map((target, index) => `    ${text(target.label)}: step${index}`)
    ].join(",\n"),
    `  }`,
    `})`,
    ``
  ].join("\n")
}

// The matrix value holding a tool's version on each machine.
const versionKey = (tool: string): string => `version-${tool}`

// A value GitHub reads as text. A whole number is written as one, which GitHub reads back as the same text and every
// linter leaves plain: `node-version: 24`. Any other text is a string.
const githubText = (value: string): Yaml.Value => /^(0|[1-9][0-9]{0,14})$/.test(value) ? Number(value) : value

// A step of the workflow and the comments written before it.
const step = (entries: ReadonlyArray<Yaml.Entry>, comments: ReadonlyArray<string> = []): Yaml.Item =>
  Yaml.item(Yaml.mapping(entries), comments)

// The setup step of a tool, or the comment that says it has no known setup action.
const renderSetup = (toolchain: Toolchain, varying: ReadonlySet<string>): Yaml.Item | string => {
  const action = setupActions.get(toolchain.name)
  if (action === undefined) return `${toolchain.name} (${toolchain.source}) has no known setup action.`
  const version = varying.has(toolchain.name)
    ? `\${{ matrix.${versionKey(toolchain.name)} }}`
    : toolchain.version
  return step([
    Yaml.entry("uses", action.uses),
    ...(version === undefined
      ? []
      : [Yaml.entry("with", Yaml.mapping([Yaml.entry(action.input, githubText(version))]))])
  ])
}

// The tools with a known setup action whose version differs between machines.
const varyingTools = (legs: ReadonlyArray<Leg>): ReadonlySet<string> => {
  const versions = new Map<string, Set<string | undefined>>()
  for (const toolchain of legs.flatMap((leg) => leg.toolchains)) {
    versions.set(toolchain.name, (versions.get(toolchain.name) ?? new Set()).add(toolchain.version))
  }
  return new Set(
    [...versions].filter(([name, values]) => values.size > 1 && setupActions.has(name)).map(([name]) => name)
  )
}

/** A runner as `runs-on` takes it: one label, or the list of labels a job names together. */
const runnerValue = (runner: string): Yaml.Value => runner.includes(",") ? Yaml.list(runner.split(",")) : runner

const renderLeg = (leg: Leg, varying: ReadonlySet<string>): Yaml.Item =>
  Yaml.item(Yaml.mapping([
    Yaml.entry("os", runnerValue(leg.runner)),
    Yaml.entry("leg", githubText(leg.id)),
    // The versions, which GitHub shows in the job's name. A machine with none of its own shows none.
    ...(leg.name === "" ? [] : [Yaml.entry("tools", leg.name)]),
    ...leg.toolchains
      .filter((toolchain) => varying.has(toolchain.name))
      .map((toolchain) => Yaml.entry(versionKey(toolchain.name), githubText(toolchain.version as string)))
  ]))

const renderLegs = (legs: ReadonlyArray<Leg>): string =>
  [hashComment(generated), ...legs.flatMap((leg) => leg.labels.map((label) => `${leg.id} //:${label}`)), ``].join("\n")

// A shell script as a step runs it, one line per command. Each line fits in the workflow's width.
const script = (lines: ReadonlyArray<string>): string => `${lines.join("\n")}\n`

// Lifts Ubuntu 24.04's restriction on the namespaces bubblewrap makes.
const liftRestriction: ReadonlyArray<string> = [
  `if [ -e /proc/sys/kernel/apparmor_restrict_unprivileged_userns ]`,
  `then`,
  `  sudo sysctl -w kernel.apparmor_restrict_unprivileged_userns=0`,
  `fi`
]

// Where a step installs or changes anything on the machine: a runner GitHub makes for the job and removes after it.
// A self-hosted runner is the machine of somebody who keeps it, and the job changes nothing there.
const hosted = "runner.environment == 'github-hosted'"
const selfHosted = "runner.environment != 'github-hosted'"

const linuxStep = (name: string, run: string, condition = "runner.os == 'Linux'"): ReadonlyArray<Yaml.Entry> => [
  Yaml.entry("name", name),
  Yaml.entry("if", condition),
  Yaml.entry("shell", "bash"),
  Yaml.entry("run", run)
]

/**
 * What a self-hosted runner is asked before the steps run in bubblewrap, which changes nothing on it: that bubblewrap
 * is installed and can make the namespace a step runs in. Each failure stops the job with one line that names what
 * the machine's owner must do, and `why` the job needs it.
 *
 * @category workflow
 * @throws {never}
 * @since 0.1.0
 */
export const selfHostedCheck = (why: string): string =>
  script([
    `if ! command -v bwrap >/dev/null 2>&1; then`,
    `  echo "::error::smithers-ci: install bubblewrap (bwrap) on this" \\`,
    `    "self-hosted runner:" \\`,
    `    "${why}." >&2`,
    `  exit 1`,
    `fi`,
    `if ! bwrap --ro-bind / / true >/dev/null 2>&1; then`,
    `  echo "::error::smithers-ci: set" \\`,
    `    "kernel.apparmor_restrict_unprivileged_userns=0 on this" \\`,
    `    "self-hosted runner, or otherwise allow unprivileged user" \\`,
    `    "namespaces: bubblewrap needs one to start, and" \\`,
    `    "${why}." >&2`,
    `  exit 1`,
    `fi`
  ])

/**
 * A step that sets bubblewrap up on a GitHub-hosted runner, and the step that checks a self-hosted one for it in
 * its place, each under `condition` too.
 */
const jailSteps = (
  name: string,
  run: string,
  why: string,
  comments: ReadonlyArray<string>,
  condition = "runner.os == 'Linux'"
): ReadonlyArray<Yaml.Item> => [
  step(linuxStep(name, run, `${condition} && ${hosted}`), comments),
  step(linuxStep(`${name} on a self-hosted runner`, selfHostedCheck(why), `${condition} && ${selfHosted}`), [
    "A self-hosted runner is left as it is: the job stops, with what to change, where bubblewrap cannot start."
  ])
]

// What the read sandbox needs on a GitHub runner, as Smithers' own workflow installs it. Linux targets are confined
// by bubblewrap, which an Ubuntu runner lacks, and Ubuntu 24.04 lets it make its namespace only once AppArmor's
// restriction is lifted. Without the step a confined target fails `sandbox_unenforceable`. macOS confines with
// seatbelt, which every Mac has.
const bubblewrapScript = script([
  `if command -v apt-get >/dev/null 2>&1; then`,
  `  sudo apt-get update -qq &&`,
  `    sudo apt-get install -y -qq --no-install-recommends bubblewrap`,
  ...liftRestriction.map((line) => `  ${line}`),
  `fi`
])

const sandboxSetup = jailSteps(
  "Install the read sandbox",
  bubblewrapScript,
  "it holds each step that names its inputs to them",
  ["A target that declares its inputs is held to them, on Linux by bubblewrap."]
)

// What keeps a step from the shared cache's token on a GitHub runner. A step can read what every process of its
// user was started with, and the shell that starts `smthrs` holds the token. So `smthrs` runs the steps where they
// see no other process, which on Linux takes bubblewrap: an Ubuntu runner lacks it, and Ubuntu 24.04 lets it make
// its namespace only once AppArmor's restriction is lifted. Nothing is installed where the repository names no
// cache. macOS and Windows have no such program: there a step can read the token.
const tokenSetup = (cache: string | undefined): ReadonlyArray<Yaml.Item> =>
  jailSteps(
    "Keep the cache's token from the steps",
    script([
      `if ! command -v bwrap >/dev/null 2>&1 &&`,
      `  command -v apt-get >/dev/null 2>&1; then`,
      `  sudo apt-get update -qq &&`,
      `    sudo apt-get install -y -qq --no-install-recommends bubblewrap`,
      `fi`,
      ...liftRestriction
    ]),
    "it keeps each step from the cache's token",
    [
      "With a shared cache, a step runs where it sees no other process and reads the cache's token from none. " +
      "That takes bubblewrap, on Linux. On macOS and Windows a step can read the token it runs beside."
    ],
    `runner.os == 'Linux'${cache === undefined ? " && vars.SMITHERS_CACHE_URL != ''" : ""}`
  )

// What a job's own `/tmp` needs on a GitHub runner: the same bubblewrap, and the same restriction lifted. Smithers
// build runs each job's targets with the job's temporary directory in place of `/tmp`, through a mount of its own.
// A hosted runner has passwordless `sudo`, and Smithers' own workflow lifts the restriction the same way.
const ownTmpSetup = jailSteps(
  "Give each job its own /tmp",
  bubblewrapScript,
  "it gives each job a /tmp of its own",
  ["Each job has a /tmp of its own, as it has a runner of its own in the original CI."]
)

// The variable that tells Smithers build two jobs must never share a `/tmp`. A runner that gives no private
// `/tmp` runs one job's targets and fails the others with the reason, where it would otherwise let a job find
// what another left there. A macOS runner has no such mount, so the plan gives each job a runner job of its own
// there (`Steps.ts`), and the one job that runs has the runner's `/tmp` to itself.
const ownTmpVariable = "SMTHRS_MACHINE_OWN_TMP"

// What observing a step needs on a GitHub runner: the tracer that records what its run reads, which an Ubuntu
// runner lacks. Without it the step still runs, and reruns on every change. macOS has no such tracer. A self-hosted
// runner is left as it is: a step there is traced when the machine has the tracer.
const tracerSetup = step(
  linuxStep(
    "Install the tracer",
    script([
      `if command -v apt-get >/dev/null 2>&1 &&`,
      `  ! command -v strace >/dev/null 2>&1; then`,
      `  sudo apt-get update -qq &&`,
      `    sudo apt-get install -y -qq --no-install-recommends strace`,
      `fi`
    ]),
    `runner.os == 'Linux' && ${hosted}`
  ),
  ["A step that names no inputs is traced, so it runs again only when a file it read changes."]
)

// The shared cache's settings in a GitHub repository, as `docs/concepts/cache.md` names them: a variable for the URL
// and secrets for the tokens. The URL given to `apply --cache` is used until the variable is set. A pull request
// reads with the read token when the repository has one, so it reuses results and stores none.
const cacheUrl = (cache: string | undefined): string =>
  cache === undefined
    ? "${{ vars.SMITHERS_CACHE_URL }}"
    : `\${{ vars.SMITHERS_CACHE_URL || '${cache.replaceAll("'", "''")}' }}`

const cacheToken =
  "${{ github.event_name == 'pull_request' && secrets.SMITHERS_CACHE_READ_TOKEN || secrets.SMITHERS_CACHE_TOKEN }}"

/**
 * What a run prints when its repository names no shared cache.
 *
 * @category constants
 * @since 0.1.0
 */
export const noSharedCache =
  "No shared cache, so results stay on this runner. To share them, set the SMITHERS_CACHE_URL variable and the SMITHERS_CACHE_TOKEN secret."

// True when two targets that may run at once could write the same files.
//
// A target held to its inputs by the read sandbox cannot write the working tree. Every other target can: a setup
// target, and a target that declares the whole repository. Such a target is safe beside another only when one of
// the two always runs after the other, when they run on different systems, or when both were split from one
// command that ran them at the same time (`Step.atOnce`). `plan.targets` is in dependency order.
//
// Two jobs on machines of their own cannot write the same files, and still run one at a time: they share the
// runner's ports and its `/tmp`, where two jobs that each start a server on one port pass on two runners.
const collides = (plan: StepPlan, narrowed: boolean): boolean => {
  const before = new Map<string, ReadonlySet<string>>()
  for (const target of plan.targets) {
    const earlier = new Set<string>(target.dependencies)
    for (const label of target.dependencies) {
      for (const other of before.get(label) as ReadonlySet<string>) earlier.add(other)
    }
    before.set(target.label, earlier)
  }
  const ordered = (one: StepTarget, other: StepTarget): boolean =>
    (before.get(one.label) as ReadonlySet<string>).has(other.label) ||
    (before.get(other.label) as ReadonlySet<string>).has(one.label)
  const apart = (one: StepTarget, other: StepTarget): boolean =>
    one.host !== undefined && other.host !== undefined && one.host !== other.host
  const together = (one: StepTarget, other: StepTarget): boolean =>
    one.atOnce && other.atOnce && one.job === other.job && one.step === other.step &&
    variantKey(one.variant) === variantKey(other.variant)
  return plan.targets.some((writer) =>
    !narrows(writer, narrowed) &&
    plan.targets.some((other) =>
      other !== writer && !ordered(writer, other) && !apart(writer, other) && !together(writer, other)
    )
  )
}

// A word as a shell reads it back unchanged.
const shellWord = (value: string): string => `'${value.replaceAll("'", "'\\''")}'`

// The first step after Node: it fails, naming each file and the command to run, when the files in the commit are not
// what `apply` writes for it, as when a pull request adds a package or a test file the generated files do not list.
// `apply` is given the cache it was given, and `--allow-docker` when it was, so it compares like with like.
const upToDate = (cache: string | undefined, allowDocker: boolean): Yaml.Item =>
  step([
    Yaml.entry("name", "Generated files are up to date"),
    Yaml.entry(
      "run",
      `npx --yes --package=smithers-ci@${release} smithers-ci apply --check${
        cache === undefined ? "" : ` --cache ${shellWord(cache)}`
      }${allowDocker ? " --allow-docker" : ""}`
    )
  ])

// The steps, with a comment that stands alone moved onto the step after it.
const steps = (pieces: ReadonlyArray<Yaml.Item | string>): Yaml.Sequence => {
  const items: Array<Yaml.Item> = []
  let pending: Array<string> = []
  for (const piece of pieces) {
    if (typeof piece === "string") pending.push(piece)
    else {
      items.push(Yaml.item(piece.value, [...pending, ...piece.comments]))
      pending = []
    }
  }
  return Yaml.sequence(items)
}

// The comments every formatter reads before the content. Biome is told to leave the file as written by one line
// for the file, Prettier by a line before each top-level key: GitHub fixes where a workflow lives and what it is
// called, so a repository's formatter reads this one file, and a formatter with other settings would rewrite it.
const unformatted = "biome-ignore-all format: generated by smithers-ci"
const keepAsWritten = ["prettier-ignore"]

const renderWorkflow = (
  plan: StepPlan,
  cache: string | undefined,
  confined: boolean,
  serial: boolean,
  observed: boolean,
  allowDocker: boolean
): string => {
  // The jobs that run on a machine of their own: each has a checkout, a home and a temporary directory.
  const machines = new Set(plan.targets.flatMap((target) => target.machine === undefined ? [] : [target.machine]))
  const apart = plan.legs.length > 0
  const varying = varyingTools(plan.legs)
  // Each machine keeps its own results: they were made under its versions.
  // A runner can be a list of labels, which an expression prints only through `join`.
  const machine = plan.runners.some((runner) => runner.includes(",")) ? "join(matrix.os, '-')" : "matrix.os"
  const cacheKey = `smithers-ci-\${{ ${machine} }}-${apart ? "${{ matrix.leg }}-" : ""}`
  // `sed` and not `awk`: a dependency checker that reads workflows (knip) reports `awk` as a program the
  // repository does not declare.
  const selection = apart
    ? `$(sed -n 's/^\${{ matrix.leg }} //p' ${legsPath})`
    : `'//...'`
  // What the workflow carries from one run to the next is Smithers build's own: its records, what each step left
  // for the steps after it, and its compiled code. No tool of a step keeps a cache there. A tool's cache is in the
  // step's own job, where the tool puts it, and is gone with the job, as on the runner of the original CI.
  const kept = [`${stateDirectory}/cache`, `${stateDirectory}/${keptFiles}`, `${stateDirectory}/${compiledCode}`]
  const matrix = apart
    ? Yaml.entry("include", Yaml.sequence(plan.legs.map((leg) => renderLeg(leg, varying))))
    : Yaml.entry("os", Yaml.list(plan.runners.map(runnerValue)))
  return Yaml.document(
    Yaml.mapping([
      Yaml.entry("name", "Smithers CI", keepAsWritten),
      Yaml.entry("on", Yaml.list(plan.triggers), keepAsWritten),
      Yaml.entry("permissions", Yaml.mapping([Yaml.entry("contents", "read")]), keepAsWritten),
      Yaml.entry(
        "jobs",
        Yaml.mapping([Yaml.entry(
          "ci",
          Yaml.mapping([
            Yaml.entry(
              "strategy",
              Yaml.mapping([Yaml.entry("fail-fast", false), Yaml.entry("matrix", Yaml.mapping([matrix]))])
            ),
            Yaml.entry("runs-on", "${{ matrix.os }}"),
            Yaml.entry(
              "steps",
              steps([
                step([Yaml.entry("uses", "actions/checkout@v4")]),
                // smithers-ci runs on this Node. A repository that sets up its own Node gets its version in the next
                // steps.
                step([
                  Yaml.entry("uses", "actions/setup-node@v4"),
                  Yaml.entry("with", Yaml.mapping([Yaml.entry("node-version", 24)]))
                ]),
                upToDate(cache, allowDocker),
                ...plan.toolchains.map((toolchain) => renderSetup(toolchain, varying)),
                // The read sandbox's step installs what keeps the token from a step, and what gives a job its own
                // `/tmp`, too. With no target held to its inputs, each has a step of its own.
                ...(confined ? sandboxSetup : [...(machines.size > 0 ? ownTmpSetup : []), ...tokenSetup(cache)]),
                ...(observed ? [tracerSetup] : []),
                step(
                  [
                    Yaml.entry("uses", "actions/cache@v4"),
                    Yaml.entry(
                      "with",
                      Yaml.mapping([
                        Yaml.entry("path", script(kept)),
                        Yaml.entry("key", `${cacheKey}\${{ github.sha }}`),
                        Yaml.entry("restore-keys", cacheKey)
                      ])
                    )
                  ],
                  [
                    "Unconfined results never reach a remote cache, so the runner keeps its own. It also keeps " +
                    "what each step left, so a later step runs without the steps before it, and the compiled " +
                    "code of smthrs, so the next run starts sooner. All of it is kept outside the checkout: a " +
                    "step that lists its files finds only the repository's."
                  ]
                ),
                ...(cache !== undefined ? [] : [
                  step([
                    Yaml.entry("name", "Shared cache"),
                    Yaml.entry("if", "${{ vars.SMITHERS_CACHE_URL == '' }}"),
                    Yaml.entry("run", `echo ${JSON.stringify(noSharedCache)}`)
                  ])
                ]),
                step(
                  [
                    Yaml.entry(
                      "run",
                      `npx --yes --package=@smthrs/cli@${release} smthrs ci ${selection}${
                        serial ? " --jobs 1" : ""
                      } --cache-dir "${stateDirectory}"`
                    ),
                    Yaml.entry(
                      "env",
                      Yaml.mapping([
                        Yaml.entry("NODE_COMPILE_CACHE", `${stateDirectory}/${compiledCode}`),
                        // Two jobs on one runner: neither finds what the other left in `/tmp`.
                        ...(machines.size > 1 ? [Yaml.entry(ownTmpVariable, "required")] : []),
                        Yaml.entry("SMITHERS_CACHE_URL", cacheUrl(cache)),
                        Yaml.entry("SMITHERS_CACHE_TOKEN", cacheToken)
                      ])
                    )
                  ],
                  serial ? ["Targets that can write the same files run one at a time."] : []
                )
              ])
            )
          ])
        )]),
        keepAsWritten
      )
    ]),
    [generated, unformatted]
  )
}

/**
 * The target map (contract 11): the label a run record reports for each
 * step. A step that shares its target with an equal step of another job has
 * an entry of its own with that target's label. At most one target runs at a
 * time when two of them could write the same files.
 */
const renderTargetMap = (plan: StepPlan, serial: boolean): string => {
  const map: TargetMap = {
    version: 1,
    targets: plan.targets.flatMap((target) =>
      [target, ...target.also].map((step) => ({
        label: `//:${target.label}`,
        job: step.job,
        step: step.step,
        variant: step.variant,
        // A split step is never one target for two jobs, so the part is the target's own.
        ...(target.part === undefined ? {} : { part: target.part }),
        ...(target.machine === undefined ? {} : { machine: target.machine })
      }))
    ),
    ...(serial ? { maxJobs: 1 } : {})
  }
  return `${JSON.stringify(map, undefined, 2)}\n`
}

const renderPackIgnore = (): string => [hashComment(generated), `*`, ``].join("\n")

const renderNotes = (plan: StepPlan): string =>
  [
    `# Not reproduced from the original CI`,
    ``,
    generated,
    ``,
    ...plan.notes.map((note) => `- ${note.replace(/[\r\n\u2028\u2029]+/g, " ")}`),
    ``
  ].join("\n")

/**
 * Renders the workspace, the targets, the target map and the workflow. The
 * workflow shares results through the cache its repository names in the
 * `SMITHERS_CACHE_URL` variable, or else through `options.cache`. With
 * `options.inheritEnv`, every target passes those variables of the machine to
 * its step.
 *
 * A tool of the repository's own never reads a generated file as one of its
 * files. Every file but the workflow is under `.smithers/`, under a name no
 * type checker, linter or formatter claims; the workflow, whose place GitHub
 * fixes, tells formatters to leave it as written; and the target map is for
 * the program alone and is not written (`written: false`).
 *
 * A target declares its step's inputs and runs confined to them. A step that
 * names none declares the whole repository and is observed: it runs again
 * only when a file its last run read has changed. When the inputs make the
 * targets too large for the one file, every target is declared that way.
 * Fails when the targets still do not fit.
 *
 * @throws {never}
 * @category rendering
 * @since 0.1.0
 */
export const renderFiles = (
  inventory: Inventory,
  plan: StepPlan,
  options?: GenerateOptions
): Result.Result<ReadonlyArray<GeneratedFile>, Failure> => {
  const fits = (content: string): boolean => new TextEncoder().encode(content).length <= maximumPackageBytes
  const passed = options?.inheritEnv ?? []
  const narrowed = renderDeclaration(inventory, plan, true, passed)
  const held = fits(narrowed)
  const targets = held ? narrowed : renderDeclaration(inventory, plan, false, passed)
  if (!fits(targets)) {
    return Result.fail({
      code: "unsupported",
      message: `The generated targets exceed the ${maximumPackageBytes} bytes Smithers reads from ${workspacePath}.`,
      part: "generate"
    })
  }
  const serial = collides(plan, held)
  return Result.succeed([
    {
      path: workflowPath,
      content: renderWorkflow(
        plan,
        options?.cache,
        // The runner needs the sandbox only when a target runs under it, and the tracer only when one is observed.
        plan.targets.some((target) => narrows(target, held)),
        serial,
        plan.targets.some((target) => observes(target, held)),
        options?.allowDocker === true
      )
    },
    { path: workspacePath, content: targets },
    { path: packIgnorePath, content: renderPackIgnore() },
    { path: targetMapPath, content: renderTargetMap(plan, serial), written: false },
    ...(plan.legs.length === 0 ? [] : [{ path: legsPath, content: renderLegs(plan.legs) }]),
    ...(plan.notes.length === 0 ? [] : [{ path: notesPath, content: renderNotes(plan) }])
  ])
}
